const row = $input.all().map((i) => i.json).find((r) => r && r.key === 'hp_cursor');
let prev = {};
try { prev = row ? JSON.parse(row.value || '{}') : {}; } catch (e) { prev = {}; }
const since = prev.ts || new Date(Date.now() - 24 * 3600000).toISOString();
const mustNot = (prev.ids && prev.ids.length) ? [{ ids: { values: prev.ids } }] : [];
const body = {
