const hits = (($input.first().json.hits || {}).hits) || [];
const SKIP_HEADERS = ['host', 'cookie', 'content-length', 'accept', 'accept-encoding', 'accept-language', 'connection', 'x-forwarded-for', 'x-forwarded-proto', 'x-forwarded-host', 'x-forwarded-port', 'x-real-ip', 'x-envoy-external-address', 'x-request-id', 'x-amzn-trace-id', 'cache-control', 'pragma', 'upgrade-insecure-requests', 'user-agent', 'content-type', 'referer', 'origin', 'te', 'priority', 'dnt'];
