  const query = String(http.query || '').slice(0, 2000);
  const headers = [].concat(http.headers || []).filter((x) => x && x.name && SKIP_HEADERS.indexOf(String(x.name).toLowerCase()) < 0).map((x) => ({ name: String(x.name).toLowerCase(), value: String(x.value || '').slice(0, 2000) }));
  const body = String(d.body || '').slice(0, 8000);
  const dets = [].concat(d.detections || []).filter((x) => x && typeof x === 'object').map((x) => ({ id: x.id || '', name: x.name || '', severity: x.severity || '', location: x.location || '', evidence: String(x.evidence || '').slice(0, 500), cves: [].concat(x.cves || []) }));
  const decoded = [].concat(d.decoded_layers || []).concat([].concat(d.artifacts || []).map((a) => ({ artifact: a })));
  const interesting = dets.length || body.trim() || decoded.length || query;
  if (!interesting) continue;
  const srcIp = String(d.src_ip || d.srcip || '');
  const text = [query, headers.map((x) => x.value).join(' '), body, JSON.stringify(decoded), dets.map((x) => x.evidence).join(' ')].join(' ');
  let all = text;
  try { all += ' ' + decodeURIComponent(text.replace(/[+]/g, ' ')); } catch (e) { all += ''; }
