  const urls = uniq((all.match(/(?:https?|ftp|tftp|ldaps?|rmi|dns|gopher|iiop|corba):[/][/][^ "'<>|;(){}]+/gi) || []).map((u) => u.slice(0, 300))).slice(0, 20);
  const hosts = uniq(urls.map((u) => { try { return new URL(u).hostname; } catch (e) { return ''; } }));
