  ollama_body: { model: 'OLLAMA_MODEL', stream: false, think: false, format: 'json', keep_alive: '15m', options: { temperature: 0.1, num_predict: 900 }, messages: [{ role: 'system', content: SYS }, { role: 'user', content: user }] }
