const src = $('Build Prompt').all().map((i) => i.json);
const res = $input.all().map((i) => i.json);
const BENIGN = /(^|[.])(w3[.]org|xmlsoap[.]org|microsoft[.]com|apache[.]org|oasis-open[.]org|xml[.]org|openxmlformats[.]org|purl[.]org|android[.]com|example[.](com|org|net))$/i;
