  const fresh = Date.now() - new Date(p.last_seen || 0).getTime() < 6 * 3600000;
  const notify = fresh && (interest >= 60 || callback || ['dropper', 'c2', 'persistence'].indexOf(stage) >= 0);
  const analysis = {
