const build = (p) => {
const a = p.analysis || {};
const s = p.static_iocs || {};
const sn = p.seen || {};
const NL = String.fromCharCode(10);
const TICKS = String.fromCharCode(96, 96, 96);
const li = (arr, n) => [].concat(arr || []).slice(0, n || 8).join(NL);
const colour = p.interest >= 80 ? 0xE74C3C : p.interest >= 60 ? 0xE67E22 : 0xF1C40F;
const req = (p.method + ' ' + p.path + (p.query ? '?' + p.query : '')).slice(0, 300);
const iocLines = [];
const urls = [].concat(s.urls || [], (a.iocs || {}).urls || []);
if (urls.length) iocLines.push('URLs: ' + Array.from(new Set(urls)).slice(0, 6).join(', '));
const ips = [].concat(s.ips || [], (a.iocs || {}).ips || []);
if (ips.length) iocLines.push('IPs: ' + Array.from(new Set(ips)).slice(0, 8).join(', '));
const doms = [].concat(s.hosts || [], (a.iocs || {}).domains || []);
if (doms.length) iocLines.push('Domains: ' + Array.from(new Set(doms)).slice(0, 8).join(', '));
const cmds = [].concat(s.commands || [], (a.iocs || {}).commands || []);
if (cmds.length) iocLines.push('Commands: ' + Array.from(new Set(cmds)).slice(0, 4).join(' ; '));
const f = [
  { name: 'Interest', value: String(p.interest) + '/100', inline: true },
  { name: 'Stage', value: a.stage || '-', inline: true },
  { name: 'Seen', value: p.count + 'x from ' + (p.src_ip_count || 0) + ' IPs', inline: true },
  { name: 'Request', value: TICKS + req + TICKS, inline: false }
];
if (sn.reason) f.push({ name: 'Why alerted', value: (sn.reason + ((sn.new_iocs || []).length ? ': ' + sn.new_iocs.slice(0, 6).join(', ') : '')).slice(0, 1024), inline: false });
if (sn.variants > 1 || sn.alert_count) f.push({ name: 'Similar seen', value: (sn.variants + ' variants, ' + sn.events + ' events since ' + String(sn.sig_first_seen || '').slice(0, 10) + (sn.last_alerted ? ', last alerted ' + String(sn.last_alerted).slice(0, 16).replace('T', ' ') : ', never alerted')).slice(0, 1024), inline: false });
const dets = [].concat(p.detections || []).map((x) => x.id + ' ' + x.name).filter((x) => x.trim());
if (dets.length) f.push({ name: 'Honeypot detections', value: li(dets, 6).slice(0, 1024), inline: false });
const cves = Array.from(new Set([].concat(p.cves || [], a.cves || [])));
if (cves.length) f.push({ name: 'CVEs', value: cves.join(', ').slice(0, 1024), inline: true });
if (a.malware_family) f.push({ name: 'Family', value: a.malware_family, inline: true });
if (iocLines.length) f.push({ name: 'IOCs', value: iocLines.join(NL).slice(0, 1024), inline: false });
if (a.decoded) f.push({ name: 'Decoded', value: (TICKS + a.decoded.slice(0, 900) + TICKS), inline: false });
if (a.why) f.push({ name: 'Why', value: a.why.slice(0, 1024), inline: false });
if (a.detection_idea) f.push({ name: 'Detection idea', value: a.detection_idea.slice(0, 1024), inline: false });
f.push({ name: 'Sample IPs', value: li(p.src_ips, 5) || '-', inline: true });
return { embed: {
  title: ('Honeypot payload: ' + (a.technique || 'unknown') + (a.target ? ' -> ' + a.target : '')).slice(0, 250),
  description: (a.summary || '').slice(0, 1000),
  color: colour, fields: f.slice(0, 25),
  footer: { text: 'Honeypot Payloads | ' + p.payload_hash + ' | sig ' + String(sn.sig_hash || '-').slice(0, 12) + ' | ' + (p.sample_alert_id || '') },
  timestamp: new Date(p.first_seen || Date.now()).toISOString()
