};
const items = $input.all().map((i) => i.json);
const NL2 = String.fromCharCode(10);
if (items.length > 3) {
  items.sort((x, y) => y.interest - x.interest);
  const lines = items.slice(0, 20).map((p) => { const a = p.analysis || {}; const sn = p.seen || {}; return '- **' + p.interest + '** ' + (a.stage || '?') + ' | ' + (a.technique || '?') + ' | ' + (p.method + ' ' + p.path).slice(0, 80) + ' | ' + (sn.reason || '') + ' | ' + String(a.summary || '').slice(0, 120); });
  return [{ json: { embed: { title: 'Honeypot payloads: ' + items.length + ' new interesting', color: 0xE67E22, description: lines.join(NL2).slice(0, 4000), footer: { text: 'Honeypot Payloads | full detail in Postgres honeypot_payloads' }, timestamp: new Date().toISOString() } } }].concat(items.slice(0, 1).map((p) => ({ json: build(p) })));
}
return items.map((p) => ({ json: build(p) }));

const q = $('Build Query').first().json;
const hits = (($input.first().json.hits || {}).hits) || [];
let st = Object.assign({}, q.prev || {});
if (hits.length) {
  const last = hits[hits.length - 1]._source.timestamp;
  const ids = hits.filter((h) => h._source.timestamp === last).map((h) => h._id);
  const carry = last === st.ts ? (st.ids || []) : [];
  st = { ts: last, ids: Array.from(new Set(carry.concat(ids))).slice(-500) };
} else if (!st.ts) {
  st = { ts: q.since, ids: [] };
}
