const rows = $input.all().map((i) => i.json).filter((r) => r && r.payload_hash);
const OAST_RE = /([a-z0-9-]+[.])+(oast[.](fun|pro|live|site|online|me)|interact[.]sh|oastify[.]com|burpcollaborator[.]net|dnslog[.]cn|ceye[.]io|requestrepo[.]com|pipedream[.]net|webhook[.]site|canarytokens[.]com)/g;
const OAST_TAIL = /(oast[.](fun|pro|live|site|online|me)|interact[.]sh|oastify[.]com|burpcollaborator[.]net|dnslog[.]cn|ceye[.]io|requestrepo[.]com|pipedream[.]net|webhook[.]site|canarytokens[.]com)$/;
const BENIGN = /(^|[.])(w3[.]org|xmlsoap[.]org|microsoft[.]com|apache[.]org|oasis-open[.]org|xml[.]org|openxmlformats[.]org|purl[.]org|android[.]com|example[.](com|org|net))$/i;
