  return x.toLowerCase()
    .replace(/eyj[a-z0-9_-]+[.][a-z0-9_-]+[.][a-z0-9_-]*/g, '<jwt>')
    .replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/g, '<uuid>')
    .replace(/[0-9]{4}-[0-9]{2}-[0-9]{2}[t ][0-9]{2}:[0-9]{2}(:[0-9]{2})?([.][0-9]+)?(z|[+-][0-9]{2}:?[0-9]{2})?/g, '<ts>')
    .replace(OAST_RE, '<oast>')
    .replace(/[0-9]{1,3}([.][0-9]{1,3}){3}/g, '<ip>')
    .replace(/[0-9a-f]{12,}/g, '<hex>')
