  const pairs = String(s || '').split('&').filter(Boolean).map((kv) => {
    const i = kv.indexOf('=');
    const k = dec(i < 0 ? kv : kv.slice(0, i));
    const v = dec(i < 0 ? '' : kv.slice(i + 1));
    return norm(k, true) + '=' + val(v);
  });
