const REALERT_DAYS = 30;
const items = $('Parse Analysis').all().map((i) => i.json);
const look = $input.first().json || {};
const sigs = look.sigs || {};
const iocs = look.iocs || {};
const now = Date.now();
const alertedSigs = {};
const alertedIocs = {};
const order = items.map((p, n) => n).sort((a, b) => (items[b].interest || 0) - (items[a].interest || 0));
for (const n of order) {
  const p = items[n];
  const g = sigs[p.sig_hash] || null;
  const keys = [].concat(p.ioc_keys || []);
  const newIocs = keys.filter((k) => !(iocs[k] && iocs[k].alerted_at) && !alertedIocs[k]);
  const lastAlerted = g && g.last_alerted ? new Date(g.last_alerted).getTime() : 0;
  const recent = lastAlerted > 0 && now - lastAlerted < REALERT_DAYS * 86400000;
  const seen = { sig_hash: p.sig_hash || null, variants: g ? Number(g.payload_count) || 0 : 0, events: g ? Number(g.event_count) || 0 : 0, sig_first_seen: g ? g.first_seen : null, alert_count: g ? Number(g.alert_count) || 0 : 0, last_alerted: g ? g.last_alerted : null, new_iocs: newIocs.slice(0, 20) };
  let notify = p.notify === true;
  if (notify && !newIocs.length) {
    if (recent) { notify = false; seen.suppressed = 'signature already alerted ' + new Date(lastAlerted).toISOString().slice(0, 16); }
    else if (p.sig_hash && alertedSigs[p.sig_hash]) { notify = false; seen.suppressed = 'same signature as ' + alertedSigs[p.sig_hash] + ' in this batch'; }
  }
  if (notify) {
    if (p.sig_hash) alertedSigs[p.sig_hash] = p.payload_hash;
    keys.forEach((k) => { alertedIocs[k] = true; });
    seen.reason = !lastAlerted ? 'new signature' : newIocs.length ? 'known signature, new indicators' : 'resurfaced after ' + REALERT_DAYS + 'd';
  }
  items[n] = Object.assign({}, p, { notify: notify, seen: seen, analysis: Object.assign({}, p.analysis || {}, { seen: seen }) });
}
return items.map((p) => ({ json: p }));
